#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#define MAXN 300
typedef long long ll;
static ll kthSmallest(ll a[MAXN][MAXN],int n,int k){ll lo=a[0][0],hi=a[n-1][n-1];while(lo<hi){ll mid=lo+(hi-lo)/2;int r=n-1,c=0,cnt=0;while(r>=0&&c<n){if(a[r][c]<=mid){cnt+=r+1;c++;}else r--;}if(cnt<k)lo=mid+1;else hi=mid;}return lo;}

