import json
import heapq

class Solution:
    def kthSmallest(self, matrix, k):
        heap = [(matrix[r][0], r, 0) for r in range(len(matrix))]
        heapq.heapify(heap)
        ans = 0
        for _ in range(k):
            ans, r, c = heapq.heappop(heap)
            if c + 1 < len(matrix):
                heapq.heappush(heap, (matrix[r][c + 1], r, c + 1))
        return ans

